values ('fq_conc_049', 'Heart of Darkness', 'exploration', 'A', 'CONCORDIUM', 'SHATTERED_HEART', 'The Void Echo Chasm opens into the Shattered Heart — the epicenter of void corruption on Xylos. Establish a forward base here. Quest giver: Officer Valen at Nexus Core Command Post.', '{"npc_id": "npc_concordium_officer", "name": "", "location": "SHATTERED_HEART"}'::jsonb, '{"min_level": 48, "reputation_required": 2820, "required_quests": ["fq_conc_048"]}'::jsonb, '[{"type": "travel", "target": "SHATTERED_HEART", "count": 1, "description": "Enter the Shattered Heart."}, {"type": "collect", "target": "thick_gel", "count": 2, "description": "Collect thick gel (x2). [Item: Thick Gel]"}]'::jsonb, '{"exp": 2500, "currency": 1300, "crd": 650, "rep": 800, "items": [{"item_id": "void_core", "quantity": 2}], "reputation": 25}'::jsonb, false, false, 'fq_conc_050', false, NULL, NULL, NULL, 'quest_concordium.json', 48)
