values ('fq_conc_050', 'The Drake''s Domain', 'boss', 'S', 'CONCORDIUM', 'SHATTERED_HEART', 'The Ashen Drake rules the Shattered Heart. Its draconic fire melts reality itself. This is your Raid Tier-1 trial. Victory will cement your legend. Quest giver: Officer Valen at Nexus Core Command Post.', '{"npc_id": "npc_concordium_officer", "name": "", "location": "SHATTERED_HEART"}'::jsonb, '{"min_level": 49, "reputation_required": 2880, "required_quests": ["fq_conc_049"]}'::jsonb, '[{"type": "kill", "target": "ASHEN_DRAKE", "count": 1, "description": "Face the Ashen Drake in its lair."}, {"type": "kill", "target": "DRAKE_MINION", "count": 5, "description": "Clear Drake Minions from the lair."}, {"type": "kill", "target": "GIGANTIC_JOTUNN", "count": 1, "description": "Defeat the Gigantic Jotunn guardian at the lair entrance."}]'::jsonb, '{"exp": 8000, "currency": 4000, "crd": 2000, "rep": 2500, "items": [{"item_id": "drake_heart", "quantity": 2}, {"item_id": "ancient_scale", "quantity": 1}, {"item_id": "con_elite_recovery_pack", "quantity": 5}], "reputation": 50}'::jsonb, false, false, 'fq_conc_051', false, NULL, NULL, NULL, 'quest_concordium.json', 49)
