values ('fq_conc_055', 'Reaver Tide', 'hunt', 'S', 'CONCORDIUM', 'SHATTERED_HEART', 'Abyssal Reavers flood from the Shattered Heart in waves. Hold the line. Not a single Reaver can reach the surface. Quest giver: Officer Valen at Nexus Core Command Post.', '{"npc_id": "npc_concordium_officer", "name": "", "location": "SHATTERED_HEART"}'::jsonb, '{"min_level": 54, "reputation_required": 3180, "required_quests": ["fq_conc_054"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_ABYSSAL_REAVER", "count": 10, "description": "Slaughter Abyssal Reavers at the breach point. [Aethel Abyssal Reaver]"}, {"type": "kill", "target": "VOID_REAVER", "count": 6, "description": "Eliminate Void Reavers flanking the main assault."}]'::jsonb, '{"exp": 5000, "currency": 2500, "crd": 1250, "rep": 1700, "items": [{"item_id": "event_horizon_fragment", "quantity": 3}], "reputation": 50}'::jsonb, false, false, 'fq_conc_056', false, NULL, NULL, NULL, 'quest_concordium.json', 54)
