values ('fq_conc_056', 'Jotunn Purge', 'boss', 'S', 'CONCORDIUM', 'SHATTERED_HEART', 'Multiple Gigantic Jotunns are converging on a critical Concordium position. (Location: Shattered Heart, Officer Valen) These ancient giants must be stopped at all costs.', '{"npc_id": "npc_concordium_officer", "name": "", "location": "SHATTERED_HEART"}'::jsonb, '{"min_level": 55, "reputation_required": 3240, "required_quests": ["fq_conc_055"]}'::jsonb, '[{"type": "kill", "target": "GIGANTIC_JOTUNN", "count": 3, "description": "Defeat three Gigantic Jotunns at the convergence point."}, {"type": "collect", "target": "core_fragment", "count": 2, "description": "Collect core fragment (x2). [Item: Core Fragment]"}]'::jsonb, '{"exp": 7000, "currency": 3500, "crd": 1750, "rep": 2200, "items": [{"item_id": "titan_core", "quantity": 2}], "reputation": 50}'::jsonb, false, false, 'fq_conc_057', false, NULL, NULL, NULL, 'quest_concordium.json', 55)
