insert into public.quests (id, title, type, rank, faction, region, description, quest_giver, requirements, objectives, rewards, repeatable, daily, quest_chain_next, popup, popup_trigger, popup_level, popup_prerequisite, source_file, sort_order)
values ('fq_iron_009', 'There Is Only One Authority Here', 'story', 'D', 'IRON_HEGEMONY', 'IRON_RAVINE', 'A Scrapfield Enforcer — a rogue combat machine that predates the Hegemony''s own war-mech program — has been claiming the central ravine as its patrol zone and attacking Hegemony survey teams on sight. Its combat protocols may actually be superior to some Hegemony-built machines, which Tink finds professionally embarrassing and Warlord Steele finds unacceptable. The Iron Hegemony is the only authority in the Iron Ravine. Enforce that fact. Quest giver: Commander Drax at Bastion Core Command Bunker.', '{"npc_id": "npc_hegemony_commander", "name": "Warlord Harkon Steele", "location": "IRON_RAVINE"}'::jsonb, '{"min_level": 8, "reputation_required": 35, "required_quests": ["fq_iron_008"]}'::jsonb, '[{"type": "kill", "target": "SCRAPFIELD_ENFORCER", "count": 1, "desc": "Defeat the Scrapfield Enforcer.", "description": "Defeat Scrapfield Enforcer (x1)."}, {"type": "kill", "target": "IRON_RAVINE_SENTINEL", "count": 1, "desc": "Destroy a Ravine Sentinel guarding the Enforcer.", "description": "Defeat Iron Ravine Sentinel (x1)."}]'::jsonb, '{"exp": 250, "currency": 150, "crd": 0, "rep": 150, "items": [{"item_id": "scrap_circuit", "quantity": 3}], "reputation": 5}'::jsonb, false, false, 'fq_iron_010', false, NULL, NULL, NULL, 'quest_iron.json', 8)
on conflict (id) do update set title = excluded.title, type = excluded.type, rank = excluded.rank, faction = excluded.faction, region = excluded.region, description = excluded.description, quest_giver = excluded.quest_giver, requirements = excluded.requirements, objectives = excluded.objectives, rewards = excluded.rewards, repeatable = excluded.repeatable, daily = excluded.daily, quest_chain_next = excluded.quest_chain_next, popup = excluded.popup, popup_trigger = excluded.popup_trigger, popup_level = excluded.popup_level, popup_prerequisite = excluded.popup_prerequisite, source_file = excluded.source_file, sort_order = excluded.sort_order;
insert into public.quests (id, title, type, rank, faction, region, description, quest_giver, requirements, objectives, rewards, repeatable, daily, quest_chain_next, popup, popup_trigger, popup_level, popup_prerequisite, source_file, sort_order)
values ('fq_iron_010', 'Strip Them to the Core', 'story', 'D', 'IRON_HEGEMONY', 'IRON_RAVINE', 'Ravine Scrap Golems are what happens when the Severance''s corrupted energy animates salvaged machinery without anyone controlling the result — walking fortresses of mismatched metal and raw aethel charge that will attack anything within range. (Location: Iron Ravine, Commander Drax) Warlord Steele does not waste time theorizing about what they are. He looks at them and sees two things: a threat to neutralize, and a salvage yield that Tink has already calculated down to the last circuit. Break them. Take what the Hegemony needs.', '{"npc_id": "npc_hegemony_commander", "name": "Warlord Harkon Steele", "location": "IRON_RAVINE"}'::jsonb, '{"min_level": 9, "reputation_required": 40, "required_quests": ["fq_iron_009"]}'::jsonb, '[{"type": "kill", "target": "RAVINE_SCRAP_GOLEM", "count": 2, "desc": "Destroy Ravine Scrap Golems.", "description": "Defeat Ravine Scrap Golem (x2)."}, {"type": "collect", "target": "scrap_core", "count": 1, "desc": "Salvage Golem core components.", "description": "Collect scrap core (x1). [Item: Scrap Core]"}]'::jsonb, '{"exp": 300, "currency": 180, "crd": 0, "rep": 180, "items": [{"item_id": "core_fragment", "quantity": 2}], "reputation": 5}'::jsonb, false, false, 'fq_iron_011', false, NULL, NULL, NULL, 'quest_iron.json', 9)
