values ('fq_iron_056', 'Jotunn Strongpoint', 'boss', 'S', 'IRON_HEGEMONY', 'SHATTERED_HEART', 'Gigantic Jotunns have fortified a position in the Heart. (Location: Shattered Heart, Commander Drax) Hegemony doctrine for strongpoints: overwhelming force.', '{"npc_id": "npc_hegemony_commander", "name": "Commander Drax", "location": "SHATTERED_HEART"}'::jsonb, '{"min_level": 55, "reputation_required": 3240, "required_quests": ["fq_iron_055"]}'::jsonb, '[{"type": "kill", "target": "GIGANTIC_JOTUNN", "count": 3, "desc": "Destroy the Jotunn strongpoint.", "description": "Defeat Gigantic Jotunn (x3)."}, {"type": "collect", "target": "core_fragment", "count": 1, "desc": "Claim the strongpoint for Hegemony.", "description": "Collect core fragment (x1). [Item: Core Fragment]"}]'::jsonb, '{"exp": 7000, "currency": 3500, "crd": 1750, "rep": 2200, "items": [{"item_id": "titan_core", "quantity": 2}], "reputation": 50}'::jsonb, false, false, 'fq_iron_057', false, NULL, NULL, NULL, 'quest_iron.json', 55)
