values ('fq_merid_036', 'Orbital Security', 'hunt', 'A', 'MERIDIAN_CARTEL', 'ORBITAL_SENTINEL_COMMAND', 'Rival factions are attempting hostile takeovers of Cartel orbital assets. (Location: Orbital Sentinel Command, Don Vercelli) Defend the portfolio.', '{"npc_id": "npc_cartel_boss", "name": "Don Vercelli", "location": "ORBITAL_SENTINEL_COMMAND"}'::jsonb, '{"min_level": 35, "reputation_required": 2040, "required_quests": ["fq_merid_035"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_RIFT_STALKER", "count": 6, "desc": "Defend against hostile takeover.", "description": "Defeat Aethel Rift Stalker (x6)."}, {"type": "kill", "target": "AETHEL_VOID_CHANNELER", "count": 3, "desc": "Neutralize competitor aggression.", "description": "Defeat Aethel Void Channeler (x3)."}]'::jsonb, '{"exp": 1500, "currency": 800, "crd": 400, "rep": 800, "items": [{"item_id": "con_elite_recovery_pack", "quantity": 3}], "reputation": 25}'::jsonb, false, false, 'fq_merid_037', false, NULL, NULL, NULL, 'quest_meridian.json', 35)
