values ('fq_merid_044', 'Abyssal Harvest', 'hunt', 'S', 'MERIDIAN_CARTEL', 'VOID_ECHO_CHASM', 'Abyssal Reavers contain concentrated void material — the most valuable substance in the known universe. (Location: Void Echo Chasm, Don Vercelli) Maximize the harvest.', '{"npc_id": "npc_cartel_boss", "name": "Don Vercelli", "location": "VOID_ECHO_CHASM"}'::jsonb, '{"min_level": 43, "reputation_required": 2520, "required_quests": ["fq_merid_043"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_ABYSSAL_REAVER", "count": 6, "desc": "Maximize Abyssal Reaver harvest.", "description": "Defeat Aethel Abyssal Reaver (x6)."}, {"type": "collect", "target": "abyssal_reaver_claw", "count": 1, "desc": "Report harvest yield to the board.", "description": "Collect abyssal reaver claw (x1). [Item: Abyssal Reaver Claw]"}]'::jsonb, '{"exp": 2200, "currency": 1100, "crd": 550, "rep": 750, "items": [{"item_id": "void_crystal_shard", "quantity": 2}], "reputation": 50}'::jsonb, false, false, 'fq_merid_045', false, NULL, NULL, NULL, 'quest_meridian.json', 43)
