values ('fq_merid_047', 'Chrono Arbitrage', 'boss', 'S', 'MERIDIAN_CARTEL', 'VOID_ECHO_CHASM', 'Chrono Wraiths create temporal loops — time arbitrage opportunities. (Location: Void Echo Chasm, Don Vercelli) But they''re damaging the Cartel''s time-is-money principle. Eliminate the arbitrage.', '{"npc_id": "npc_cartel_boss", "name": "Don Vercelli", "location": "VOID_ECHO_CHASM"}'::jsonb, '{"min_level": 46, "reputation_required": 2700, "required_quests": ["fq_merid_046"]}'::jsonb, '[{"type": "kill", "target": "CHRONO_WRAITH", "count": 2, "desc": "Eliminate Chrono Wraith time arbitrage.", "description": "Defeat Chrono Wraith (x2)."}, {"type": "collect", "target": "monster_material", "count": 1, "desc": "Confirm temporal market stability.", "description": "Collect monster material (x1). [Item: Monster Material]"}]'::jsonb, '{"exp": 3500, "currency": 1800, "crd": 900, "rep": 1100, "items": [{"item_id": "quantum_distortion_stone", "quantity": 1}], "reputation": 50}'::jsonb, false, false, 'fq_merid_048', false, NULL, NULL, NULL, 'quest_meridian.json', 46)
