values ('fq_merid_048', 'Jotunn Acquisition', 'boss', 'S', 'MERIDIAN_CARTEL', 'VOID_ECHO_CHASM', 'A Gigantic Jotunn sits on the largest void mineral deposit in the chasm. (Location: Void Echo Chasm, Kip) Hostile takeover required.', '{"npc_id": "npc_ruin_diver", "name": "Kip", "location": "VOID_ECHO_CHASM"}'::jsonb, '{"min_level": 47, "reputation_required": 2760, "required_quests": ["fq_merid_047"]}'::jsonb, '[{"type": "kill", "target": "GIGANTIC_JOTUNN", "count": 1, "desc": "Execute hostile takeover of Jotunn territory.", "description": "Defeat Gigantic Jotunn (x1)."}, {"type": "collect", "target": "core_fragment", "count": 1, "desc": "File mineral deposit claim.", "description": "Collect core fragment (x1). [Item: Core Fragment]"}]'::jsonb, '{"exp": 3500, "currency": 1800, "crd": 900, "rep": 1000, "items": [{"item_id": "titan_core", "quantity": 1}], "reputation": 50}'::jsonb, false, false, 'fq_merid_049', false, NULL, NULL, NULL, 'quest_meridian.json', 47)
