values ('fq_merid_054', 'Temporal Market Correction', 'boss', 'S', 'MERIDIAN_CARTEL', 'VOID_ECHO_CHASM', 'Chrono Wraiths are causing temporal market volatility. (Location: Void Echo Chasm, Don Vercelli) The Cartel requires market stability. Correct the market.', '{"npc_id": "npc_cartel_boss", "name": "Don Vercelli", "location": "VOID_ECHO_CHASM"}'::jsonb, '{"min_level": 53, "reputation_required": 3120, "required_quests": ["fq_merid_053"]}'::jsonb, '[{"type": "kill", "target": "CHRONO_WRAITH", "count": 3, "desc": "Correct temporal market volatility.", "description": "Defeat Chrono Wraith (x3)."}, {"type": "collect", "target": "monster_material", "count": 1, "desc": "Confirm market correction.", "description": "Collect monster material (x1). [Item: Monster Material]"}]'::jsonb, '{"exp": 6500, "currency": 3200, "crd": 1600, "rep": 2000, "items": [{"item_id": "quantum_distortion_stone", "quantity": 2}], "reputation": 50}'::jsonb, false, false, 'fq_merid_055', false, NULL, NULL, NULL, 'quest_meridian.json', 53)
