values ('fq_merid_055', 'Heart Market Share', 'hunt', 'S', 'MERIDIAN_CARTEL', 'SHATTERED_HEART', 'Seize majority market share in the Shattered Heart. Competitor liquidation required. Quest giver: Don Vercelli at Port Meridian Cartel Headquarters.', '{"npc_id": "npc_cartel_boss", "name": "Don Vercelli", "location": "SHATTERED_HEART"}'::jsonb, '{"min_level": 54, "reputation_required": 3180, "required_quests": ["fq_merid_054"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_ABYSSAL_REAVER", "count": 10, "desc": "Seize market share from competitors.", "description": "Defeat Aethel Abyssal Reaver (x10)."}, {"type": "kill", "target": "VOID_REAVER", "count": 6, "desc": "Eliminate remaining competition.", "description": "Defeat Void Reaver (x6)."}]'::jsonb, '{"exp": 5000, "currency": 2500, "crd": 1250, "rep": 1700, "items": [{"item_id": "event_horizon_fragment", "quantity": 3}], "reputation": 50}'::jsonb, false, false, 'fq_merid_056', false, NULL, NULL, NULL, 'quest_meridian.json', 54)
