values ('fq_merid_057', 'Tyrant Divestment', 'boss', 'S', 'MERIDIAN_CARTEL', 'SHATTERED_HEART', 'Crystal Tyrants hold valuable assets. (Location: Shattered Heart, Don Vercelli) Divest them — forcibly.', '{"npc_id": "npc_cartel_boss", "name": "Don Vercelli", "location": "SHATTERED_HEART"}'::jsonb, '{"min_level": 56, "reputation_required": 3300, "required_quests": ["fq_merid_056"]}'::jsonb, '[{"type": "kill", "target": "CRYSTAL_TYRANT", "count": 2, "desc": "Divest Tyrant-held assets.", "description": "Defeat Crystal Tyrant (x2)."}, {"type": "collect", "target": "monster_material", "count": 1, "desc": "File divestment completion report.", "description": "Collect monster material (x1). [Item: Monster Material]"}]'::jsonb, '{"exp": 7200, "currency": 3600, "crd": 1800, "rep": 2300, "items": [{"item_id": "quantum_distortion_stone", "quantity": 2}], "reputation": 50}'::jsonb, false, false, 'fq_merid_058', false, NULL, NULL, NULL, 'quest_meridian.json', 56)
