values ('fq_merid_059', 'Fragmenter Bankruptcy', 'boss', 'S', 'MERIDIAN_CARTEL', 'VOID_ECHO_CHASM', 'Soul Fragmenters are operating at a loss — our loss. (Location: Void Echo Chasm, Don Vercelli) Force them into bankruptcy.', '{"npc_id": "npc_cartel_boss", "name": "Don Vercelli", "location": "VOID_ECHO_CHASM"}'::jsonb, '{"min_level": 58, "reputation_required": 3420, "required_quests": ["fq_merid_058"]}'::jsonb, '[{"type": "kill", "target": "SOUL_FRAGMENTER", "count": 3, "desc": "Force Fragmenter bankruptcy.", "description": "Defeat Soul Fragmenter (x3)."}, {"type": "kill", "target": "VOID_STALKER", "count": 1, "desc": "Seize Stalker-held Fragmenter assets.", "description": "Defeat Void Stalker (x1)."}]'::jsonb, '{"exp": 8000, "currency": 4000, "crd": 2000, "rep": 2500, "items": [{"item_id": "brainwave_oscillator", "quantity": 2}], "reputation": 50}'::jsonb, false, false, 'fq_merid_060', false, NULL, NULL, NULL, 'quest_meridian.json', 58)
