values ('fq_merid_086', 'Apex Titan Dividend', 'boss', 'S', 'MERIDIAN_CARTEL', 'CRADLE_EXPANSE', 'The Gravity Titan''s third manifestation pays an even larger dividend. (Location: Cradle Expanse, Don Vercelli) The Cartel always collects.', '{"npc_id": "npc_cartel_boss", "name": "Don Vercelli", "location": "CRADLE_EXPANSE"}'::jsonb, '{"min_level": 85, "reputation_required": 5040, "required_quests": ["fq_merid_085"]}'::jsonb, '[{"type": "kill", "target": "GRAVITY_TITAN", "count": 1, "desc": "Collect the Titan dividend.", "description": "Defeat Gravity Titan (x1)."}, {"type": "collect", "target": "core_fragment", "count": 1, "desc": "Confirm dividend collection.", "description": "Collect core fragment (x1). [Item: Core Fragment]"}]'::jsonb, '{"exp": 14000, "currency": 7000, "crd": 3500, "rep": 4500, "items": [{"item_id": "titan_core", "quantity": 4}, {"item_id": "gravity_well_core", "quantity": 3}], "reputation": 50}'::jsonb, false, false, 'fq_merid_087', false, NULL, NULL, NULL, 'quest_meridian.json', 84)
