insert into public.quests (id, title, type, rank, faction, region, description, quest_giver, requirements, objectives, rewards, repeatable, daily, quest_chain_next, popup, popup_trigger, popup_level, popup_prerequisite, source_file, sort_order)
values ('fq_omni_002', 'Recovery Protocol: Survey Fleet', 'story', 'D', 'OMNICORP', 'HIGHLAND_PLATEAU', 'OmniCorp''s Survey Bots are the most advanced autonomous assessment units on Xylos — which makes it particularly inconvenient that four of them have gone offline in the Highland Plateau''s northern grid sector. Director Vey''s analysis is concise: the Plateau Drones that are swarming the area malfunctioned when OmniCorp''s initial survey signals overwhelmed their primitive navigation systems. The Survey Bots'' data cores contain Xylos asset maps that no other faction has. Recover them before someone else does. Quest giver: Tech Officer 404 at Skybridge Reactor Control Room.', '{"npc_id": "npc_omnicorp_technician", "name": "Director Astra Vey", "location": "HIGHLAND_PLATEAU"}'::jsonb, '{"min_level": 1, "reputation_required": 5, "required_quests": ["fq_omni_001"]}'::jsonb, '[{"type": "kill", "target": "OMNI_SURVEY_BOT", "count": 4, "desc": "Neutralize malfunctioning Survey Bots.", "description": "Defeat Omni Survey Bot (x4)."}, {"type": "collect", "target": "sensor_chip", "count": 3, "desc": "Recover Survey Bot data cores.", "description": "Collect sensor chip (x3). [Item: Sensor Chip]"}]'::jsonb, '{"exp": 55, "currency": 35, "crd": 0, "rep": 35, "items": [{"item_id": "scrap_circuit", "quantity": 2}], "reputation": 5}'::jsonb, false, false, 'fq_omni_003', false, NULL, NULL, NULL, 'quest_omnicorp.json', 1)
on conflict (id) do update set title = excluded.title, type = excluded.type, rank = excluded.rank, faction = excluded.faction, region = excluded.region, description = excluded.description, quest_giver = excluded.quest_giver, requirements = excluded.requirements, objectives = excluded.objectives, rewards = excluded.rewards, repeatable = excluded.repeatable, daily = excluded.daily, quest_chain_next = excluded.quest_chain_next, popup = excluded.popup, popup_trigger = excluded.popup_trigger, popup_level = excluded.popup_level, popup_prerequisite = excluded.popup_prerequisite, source_file = excluded.source_file, sort_order = excluded.sort_order;
insert into public.quests (id, title, type, rank, faction, region, description, quest_giver, requirements, objectives, rewards, repeatable, daily, quest_chain_next, popup, popup_trigger, popup_level, popup_prerequisite, source_file, sort_order)
values ('fq_omni_003', 'Calibration by Elimination', 'story', 'D', 'OMNICORP', 'HIGHLAND_PLATEAU', 'The Plateau Drones were OmniCorp''s own early-model survey units, deployed on the Highland Plateau in a previous assessment cycle and never retrieved — now operating outside their original parameters due to Xylos''s aethel-charged atmosphere corrupting their navigation firmware. Director Astra Vey considers them a known liability. Their salvage value is marginal. Their interference with current operations is not. OmniCorp''s standard approach to hardware that costs more to fix than to replace: controlled demolition. Quest giver: Director Sterling at The Spire Executive Floor.', '{"npc_id": "npc_omnicorp_executive", "name": "Director Astra Vey", "location": "HIGHLAND_PLATEAU"}'::jsonb, '{"min_level": 2, "reputation_required": 10, "required_quests": ["fq_omni_002"]}'::jsonb, '[{"type": "kill", "target": "PLATEAU_DRONE", "count": 5, "desc": "Recalibrate Plateau Drones.", "description": "Defeat Plateau Drone (x5)."}, {"type": "collect", "target": "circuit_fragment", "count": 2, "desc": "Submit debris for failure analysis.", "description": "Collect circuit fragment (x2). [Item: Circuit Fragment]"}]'::jsonb, '{"exp": 70, "currency": 40, "crd": 0, "rep": 40, "items": [{"item_id": "damaged_servo_motor", "quantity": 1}], "reputation": 5}'::jsonb, false, false, 'fq_omni_004', false, NULL, NULL, NULL, 'quest_omnicorp.json', 2)
