values ('fq_omni_034', 'Corrupted Behemoth Purge', 'boss', 'A', 'OMNICORP', 'CRADLE_EXPANSE', 'Aethel Corrupted Behemoths are corrupted data given physical form. (Location: Cradle Expanse, Director Sterling) Delete them.', '{"npc_id": "npc_omnicorp_executive", "name": "Director Sterling", "location": "CRADLE_EXPANSE"}'::jsonb, '{"min_level": 33, "reputation_required": 1920, "required_quests": ["fq_omni_033"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_CORRUPTED_BEHEMOTH", "count": 2, "desc": "Delete Corrupted Behemoths.", "description": "Defeat Aethel Corrupted Behemoth (x2)."}, {"type": "collect", "target": "raw_aethel_fragment", "count": 1, "desc": "Confirm data deletion.", "description": "Collect raw aethel fragment (x1). [Item: Raw Aethel Fragment]"}]'::jsonb, '{"exp": 1600, "currency": 850, "crd": 425, "rep": 850, "items": [{"item_id": "aethel_fragment", "quantity": 2}], "reputation": 25}'::jsonb, false, false, 'fq_omni_035', false, NULL, NULL, NULL, 'quest_omnicorp.json', 32)
