values ('fq_omni_035', 'Abyssal Firewall', 'boss', 'A', 'OMNICORP', 'CRADLE_EXPANSE', 'Aethel Abyssal Reavers are attempting network intrusion at the orbital level. (Location: Cradle Expanse, Warden AI) Deploy counter-intrusion measures.', '{"npc_id": "npc_grid_security", "name": "Warden AI", "location": "CRADLE_EXPANSE"}'::jsonb, '{"min_level": 34, "reputation_required": 1980, "required_quests": ["fq_omni_034"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_ABYSSAL_REAVER", "count": 4, "desc": "Deploy counter-intrusion measures.", "description": "Defeat Aethel Abyssal Reaver (x4)."}, {"type": "collect", "target": "raw_aethel_fragment", "count": 1, "desc": "Report firewall integrity.", "description": "Collect raw aethel fragment (x1). [Item: Raw Aethel Fragment]"}]'::jsonb, '{"exp": 1800, "currency": 950, "crd": 475, "rep": 950, "items": [{"item_id": "event_horizon_fragment", "quantity": 1}], "reputation": 25}'::jsonb, false, false, 'fq_omni_036', false, NULL, NULL, NULL, 'quest_omnicorp.json', 33)
