values ('fq_omni_047', 'Chrono Runtime Error', 'boss', 'S', 'OMNICORP', 'VOID_ECHO_CHASM', 'Chrono Wraiths generate temporal runtime errors. (Location: Void Echo Chasm, Warden AI) Time is a resource — these errors waste it. Terminate all Wraith processes.', '{"npc_id": "npc_grid_security", "name": "Warden AI", "location": "VOID_ECHO_CHASM"}'::jsonb, '{"min_level": 46, "reputation_required": 2700, "required_quests": ["fq_omni_046"]}'::jsonb, '[{"type": "kill", "target": "CHRONO_WRAITH", "count": 2, "desc": "Terminate Wraith runtime errors.", "description": "Defeat Chrono Wraith (x2)."}, {"type": "collect", "target": "core_fragment", "count": 1, "desc": "Report temporal stability restored.", "description": "Collect core fragment (x1). [Item: Core Fragment]"}]'::jsonb, '{"exp": 3500, "currency": 1800, "crd": 900, "rep": 1100, "items": [{"item_id": "quantum_distortion_stone", "quantity": 1}], "reputation": 50}'::jsonb, false, false, 'fq_omni_048', false, NULL, NULL, NULL, 'quest_omnicorp.json', 45)
