values ('fq_omni_085', 'Apex Harbinger Uninstall', 'boss', 'S', 'OMNICORP', 'VOID_ECHO_CHASM', 'The Apex Abyss Harbinger has reinstalled itself. (Location: Void Echo Chasm, Director Sterling) Execute permanent uninstall.', '{"npc_id": "npc_omnicorp_executive", "name": "", "location": "VOID_ECHO_CHASM"}'::jsonb, '{"min_level": 84, "reputation_required": 4980, "required_quests": ["fq_omni_084"]}'::jsonb, '[{"type": "kill", "target": "ABYSS_HARBINGER", "count": 1, "desc": "Execute permanent uninstall.", "description": "Defeat Abyss Harbinger (x1)."}, {"type": "collect", "target": "void_core", "count": 1, "desc": "Verify uninstall complete.", "description": "Collect void core (x1). [Item: Void Core]"}]'::jsonb, '{"exp": 13000, "currency": 6500, "crd": 3250, "rep": 4200, "items": [{"item_id": "void_core", "quantity": 5}, {"item_id": "event_horizon_fragment_l", "quantity": 3}], "reputation": 50}'::jsonb, false, false, 'fq_omni_086', false, NULL, NULL, NULL, 'quest_omnicorp.json', 83)
