values ('fq_omni_086', 'Apex Titan Format', 'boss', 'S', 'OMNICORP', 'CRADLE_EXPANSE', 'The Gravity Titan has reformatted. (Location: Cradle Expanse, Director Sterling) Execute full disk format on Titan instance.', '{"npc_id": "npc_omnicorp_executive", "name": "", "location": "CRADLE_EXPANSE"}'::jsonb, '{"min_level": 85, "reputation_required": 5040, "required_quests": ["fq_omni_085"]}'::jsonb, '[{"type": "kill", "target": "GRAVITY_TITAN", "count": 1, "desc": "Execute full disk format on Titan.", "description": "Defeat Gravity Titan (x1)."}, {"type": "collect", "target": "monster_material", "count": 1, "desc": "Verify format complete.", "description": "Collect monster material (x1). [Item: Monster Material]"}]'::jsonb, '{"exp": 14000, "currency": 7000, "crd": 3500, "rep": 4500, "items": [{"item_id": "titan_core", "quantity": 4}, {"item_id": "gravity_well_core", "quantity": 3}], "reputation": 50}'::jsonb, false, false, 'fq_omni_087', false, NULL, NULL, NULL, 'quest_omnicorp.json', 84)
