insert into public.quests (id, title, type, rank, faction, region, description, quest_giver, requirements, objectives, rewards, repeatable, daily, quest_chain_next, popup, popup_trigger, popup_level, popup_prerequisite, source_file, sort_order)
values ('fq_shard_003', 'The Lost Are Not Evil', 'story', 'D', 'CHILDREN_OF_THE_SHARD', 'GLOWVINE_FOREST', 'Brother Silas, who walks the forest''s perimeter each dawn reciting Shard invocations against the day the Severance ends, explains: Glowvine Stalkers are not hunters by nature — they were once benign creatures of the sacred forest, corrupted when the Industrial factions began drilling near the forest''s aethel nodes. (Location: Glowvine Forest, Brother Silas) They hunt because they are in pain. They are lost because the Shard''s light has been dimmed by others'' greed. The Children do not condemn the lost. They guide them back, even if guiding requires force.', '{"npc_id": "npc_forest_acolyte", "name": "Elder Malakor", "location": "GLOWVINE_FOREST"}'::jsonb, '{"min_level": 2, "reputation_required": 10, "required_quests": ["fq_shard_002"]}'::jsonb, '[{"type": "kill", "target": "GLOWVINE_STALKER", "count": 5, "description": "Guide Glowvine Stalkers."}, {"type": "collect", "target": "glowvine_seed", "count": 2, "description": "Collect glowvine seed (x2). [Item: Glowvine Seed]"}]'::jsonb, '{"exp": 70, "currency": 40, "crd": 0, "rep": 40, "items": [{"item_id": "dark_energy_fragment", "quantity": 1}], "reputation": 5}'::jsonb, false, false, 'fq_shard_004', false, NULL, NULL, NULL, 'quest_shard.json', 2)
on conflict (id) do update set title = excluded.title, type = excluded.type, rank = excluded.rank, faction = excluded.faction, region = excluded.region, description = excluded.description, quest_giver = excluded.quest_giver, requirements = excluded.requirements, objectives = excluded.objectives, rewards = excluded.rewards, repeatable = excluded.repeatable, daily = excluded.daily, quest_chain_next = excluded.quest_chain_next, popup = excluded.popup, popup_trigger = excluded.popup_trigger, popup_level = excluded.popup_level, popup_prerequisite = excluded.popup_prerequisite, source_file = excluded.source_file, sort_order = excluded.sort_order;
insert into public.quests (id, title, type, rank, faction, region, description, quest_giver, requirements, objectives, rewards, repeatable, daily, quest_chain_next, popup, popup_trigger, popup_level, popup_prerequisite, source_file, sort_order)
values ('fq_shard_004', 'Returning What Belongs to the Cycle', 'story', 'D', 'CHILDREN_OF_THE_SHARD', 'GLOWVINE_FOREST', 'The Feral Rootlings strangling the forest floor are a symptom of the deepest wound the Children of the Shard acknowledge: energy that has been cut off from its cycle by the Severance''s ongoing aftermath, pooling and corrupting instead of flowing and nourishing. (Location: Glowvine Forest, High Priestess Lyr) Elder Malakor says the Rootlings are the forest''s attempt to hold onto energy it fears losing — a kind of grief, expressed in root and fiber. Untangle them. Return what they are hoarding to the soil. This is the Children''s most sacred act: restoration.', '{"npc_id": "npc_high_priest", "name": "Elder Malakor", "location": "GLOWVINE_FOREST"}'::jsonb, '{"min_level": 3, "reputation_required": 15, "required_quests": ["fq_shard_003"]}'::jsonb, '[{"type": "kill", "target": "FERAL_ROOTLING", "count": 5, "description": "Untangle Feral Rootlings."}, {"type": "collect", "target": "living_root", "count": 3, "description": "Collect living root (x3). [Item: Living Root]"}]'::jsonb, '{"exp": 80, "currency": 50, "crd": 0, "rep": 50, "items": [{"item_id": "shardroot_vine", "quantity": 2}], "reputation": 5}'::jsonb, false, false, 'fq_shard_005', false, NULL, NULL, NULL, 'quest_shard.json', 3)
on conflict (id) do update set title = excluded.title, type = excluded.type, rank = excluded.rank, faction = excluded.faction, region = excluded.region, description = excluded.description, quest_giver = excluded.quest_giver, requirements = excluded.requirements, objectives = excluded.objectives, rewards = excluded.rewards, repeatable = excluded.repeatable, daily = excluded.daily, quest_chain_next = excluded.quest_chain_next, popup = excluded.popup, popup_trigger = excluded.popup_trigger, popup_level = excluded.popup_level, popup_prerequisite = excluded.popup_prerequisite, source_file = excluded.source_file, sort_order = excluded.sort_order;
insert into public.quests (id, title, type, rank, faction, region, description, quest_giver, requirements, objectives, rewards, repeatable, daily, quest_chain_next, popup, popup_trigger, popup_level, popup_prerequisite, source_file, sort_order)
values ('fq_shard_005', 'The Shard Has Heard You', 'tutorial', 'D', 'CHILDREN_OF_THE_SHARD', 'SANCTUM', 'Oracle Seraphel — the Children''s seer, whose visions are trusted above all earthly counsel — has spoken to Elder Malakor: the Shard has heard your actions in the forest and found your soul-frequency resonant. This is the Children''s deepest honor. The Sanctum, hidden in the heart of the jungle, is where those found worthy are attuned to a specialization — not chosen, but revealed. The Shard shows you what you already are. Seraphel will perform the calibration. Come as you are. Come honestly.', '{"npc_id": "npc_shard_class_trainer", "name": "Oracle Seraphel", "location": "SANCTUM"}'::jsonb, '{"min_level": 4, "reputation_required": 20, "required_quests": ["fq_shard_004"], "required_items": ["recomendation_letters"]}'::jsonb, '[{"type": "interact", "target": "npc_shard_class_trainer", "count": 1, "description": "Receive calibration from Oracle Seraphel. (Oracle Seraphel at Sanctum Deep Chamber)"}, {"type": "interact", "target": "class_change_screen", "count": 1, "description": "Attune to your chosen path."}, {"type": "kill", "target": "GLOWVINE_SPRITE", "count": 3, "description": "Demonstrate harmony against the restless Hare. [Glowvine Sprite]"}]'::jsonb, '{"exp": 400, "currency": 200, "crd": 0, "rep": 150, "items": [{"item_id": "wpn_apprentice_staff", "quantity": 1}, {"item_id": "armor_cloth_robes", "quantity": 1}, {"item_id": "rare_emblem", "quantity": 1}, {"item_id": "echo_memory_core_low", "quantity": 1}], "reputation": 5}'::jsonb, false, false, 'fq_shard_006', true, 'on_quest_complete', 4, 'fq_shard_004', 'quest_shard.json', 4)
