values ('ally_vera', 'VERA_SOLACE', 'Vera Solace', 'Rare', 'Healer', 'A field medic who served three rotations in the Concordium border pacification campaigns. Vera carries the weight of every soldier she couldn''t save, and channels that grief into ensuring no one in her current party meets the same fate.', 'Cradle Outer Ring', 'CONCORDIUM', '{"hp": 105, "mp": 145, "atk": 55, "def": 90, "agi": 80, "per": 135}'::jsonb, 'al_vera_pas', 'al_vera_act', 2, 50, 0.93, 2, 9)
