insert into public.npcs (npc_id, name, title, role, faction, location, region_id, description, personality, greeting, shop_inventory, dialogue_tree, buy_currency, rest_currency, sell_note, quest_category, reward_currency, available_services, actions, sort_order)
values ('npc_novice_researcher', 'Novice Finn', 'Field Researcher', 'INFO', 'THE_ARCANUM_SEEKERS', 'Crystal Slope Field Station', 'CRYSTAL_SLOPE', 'Finn is enthusiastic to a fault and has already accidentally detonated two crystal clusters this season.', 'eager_clumsy', 'Oh! You''re here! I was just about to try something probably-safe!', NULL, 'dialog_finn_novice', NULL, NULL, NULL, NULL, NULL, '["INFO"]'::jsonb, '[]'::jsonb, 14)
