insert into public.npcs (npc_id, name, title, role, faction, location, region_id, description, personality, greeting, shop_inventory, dialogue_tree, buy_currency, rest_currency, sell_note, quest_category, reward_currency, available_services, actions, sort_order)
values ('npc_glass_collector', 'Mina', 'Crystal Harvester', 'MERCHANT', 'NONE', 'Fractured Glass Valley Market', 'FRACTURED_GLASS_VALLEY', 'Mina has spent years combing the Valley for pure Cradle Glass fragments. She sells the extras and keeps the finest for herself.', 'focused_mercantile', 'I''ll tell you right now — the good pieces aren''t for sale. But I have plenty of the rest.', 'shop_crystal_01', 'dialog_glass_collector', NULL, NULL, NULL, NULL, NULL, '["BUY", "SELL"]'::jsonb, '["open_shop"]'::jsonb, 15)
on conflict (npc_id) do update set name=excluded.name, title=excluded.title, role=excluded.role, faction=excluded.faction, location=excluded.location, region_id=excluded.region_id, description=excluded.description, personality=excluded.personality, greeting=excluded.greeting, shop_inventory=excluded.shop_inventory, dialogue_tree=excluded.dialogue_tree, buy_currency=excluded.buy_currency, rest_currency=excluded.rest_currency, sell_note=excluded.sell_note, quest_category=excluded.quest_category, reward_currency=excluded.reward_currency, available_services=excluded.available_services, actions=excluded.actions, sort_order=excluded.sort_order;
insert into public.npcs (npc_id, name, title, role, faction, location, region_id, description, personality, greeting, shop_inventory, dialogue_tree, buy_currency, rest_currency, sell_note, quest_category, reward_currency, available_services, actions, sort_order)
values ('npc_cave_spelunker', 'Dax', 'Deep Delver', 'INFO', 'NONE', 'Resonance Caverns Entrance', 'RESONANCE_CAVERNS', 'Dax descends into the Caverns daily and emerges with more data than anyone else alive. He''s partially deaf from the resonance hum.', 'casual_brave', 'What? Oh — yeah. Deep cave, lots of crystals, definitely haunted. Want specifics?', NULL, 'dialog_cave_dax', NULL, NULL, NULL, NULL, NULL, '["INFO"]'::jsonb, '[]'::jsonb, 16)
on conflict (npc_id) do update set name=excluded.name, title=excluded.title, role=excluded.role, faction=excluded.faction, location=excluded.location, region_id=excluded.region_id, description=excluded.description, personality=excluded.personality, greeting=excluded.greeting, shop_inventory=excluded.shop_inventory, dialogue_tree=excluded.dialogue_tree, buy_currency=excluded.buy_currency, rest_currency=excluded.rest_currency, sell_note=excluded.sell_note, quest_category=excluded.quest_category, reward_currency=excluded.reward_currency, available_services=excluded.available_services, actions=excluded.actions, sort_order=excluded.sort_order;
insert into public.npcs (npc_id, name, title, role, faction, location, region_id, description, personality, greeting, shop_inventory, dialogue_tree, buy_currency, rest_currency, sell_note, quest_category, reward_currency, available_services, actions, sort_order)
values ('npc_peak_watcher', 'Watcher Vane', 'Observatory Guard', 'QUEST_GIVER', 'THE_ARCANUM_SEEKERS', 'Shard Pulse Peak Observation Post', 'SHARD_PULSE_PEAK', 'Watcher Vane monitors Shard energy peaks from the highest post in the region. She hasn''t slept a full night in two years.', 'intense_vigilant', 'The readings spiked again. Something is building. I need a runner.', NULL, 'dialog_peak_watcher', NULL, NULL, NULL, NULL, NULL, '["QUEST"]'::jsonb, '[]'::jsonb, 17)
on conflict (npc_id) do update set name=excluded.name, title=excluded.title, role=excluded.role, faction=excluded.faction, location=excluded.location, region_id=excluded.region_id, description=excluded.description, personality=excluded.personality, greeting=excluded.greeting, shop_inventory=excluded.shop_inventory, dialogue_tree=excluded.dialogue_tree, buy_currency=excluded.buy_currency, rest_currency=excluded.rest_currency, sell_note=excluded.sell_note, quest_category=excluded.quest_category, reward_currency=excluded.reward_currency, available_services=excluded.available_services, actions=excluded.actions, sort_order=excluded.sort_order;
insert into public.npcs (npc_id, name, title, role, faction, location, region_id, description, personality, greeting, shop_inventory, dialogue_tree, buy_currency, rest_currency, sell_note, quest_category, reward_currency, available_services, actions, sort_order)
values ('npc_hegemony_commander', 'Commander Drax', 'Bastion Leader', 'QUEST_GIVER', 'IRON_HEGEMONY', 'Bastion Core Command Bunker', 'BASTION_CORE', 'Commander Drax runs Bastion Core''s offensive operations with zero tolerance for failure or excuses. His record is unbroken because he breaks people first.', 'aggressive_efficient', 'You want a job? Prove you''re worth the oxygen first.', NULL, 'dialog_drax_main', NULL, NULL, NULL, NULL, NULL, '["QUEST"]'::jsonb, '[]'::jsonb, 18)
on conflict (npc_id) do update set name=excluded.name, title=excluded.title, role=excluded.role, faction=excluded.faction, location=excluded.location, region_id=excluded.region_id, description=excluded.description, personality=excluded.personality, greeting=excluded.greeting, shop_inventory=excluded.shop_inventory, dialogue_tree=excluded.dialogue_tree, buy_currency=excluded.buy_currency, rest_currency=excluded.rest_currency, sell_note=excluded.sell_note, quest_category=excluded.quest_category, reward_currency=excluded.reward_currency, available_services=excluded.available_services, actions=excluded.actions, sort_order=excluded.sort_order;
