values ('npc_altar_guardian', 'Guardian Rell', 'Altar Defense', 'INFO', 'CHILDREN_OF_THE_SHARD', 'Heartwood Altar', 'HEARTWOOD_ALTAR', 'Guardian Rell is the last of the Altar''s sworn defenders. She speaks rarely and only when she has something worth saying.', 'stoic_protective', 'State your purpose at the Altar. Those who lie do not leave easily.', NULL, 'dialog_rell_guardian', NULL, NULL, NULL, NULL, NULL, '["INFO"]'::jsonb, '[]'::jsonb, 40)
