values ('npc_badland_survivor', 'Rex', 'Wasteland Survivor', 'MERCHANT', 'NONE', 'Scorched Badlands Trading Post', 'SCORCHED_BADLANDS', 'Rex survived a collapse in the Mesa Warpath and set up the only trading post between the Badlands and the Fortress. He charges accordingly.', 'blunt_survivalist', 'Prices are high because everything out here costs blood to move. Pay or move on.', 'shop_wasteland_01', 'dialog_rex_survivor', NULL, NULL, NULL, NULL, NULL, '["BUY", "SELL"]'::jsonb, '["open_shop"]'::jsonb, 44)
