values ('npc_warpath_veteran', 'Veteran Gorok', 'Warpath Defender', 'QUEST_GIVER', 'STARFORGED_LEGION', 'Mesa Warpath Memorial', 'MESA_WARPATH', 'Veteran Gorok fought in the Mesa Warpath campaigns and returned to guard the memorial. He gives contracts to those who understand what they''re walking into.', 'mournful_resolved', 'Read the names on the wall before you take any contract from me. All of them.', NULL, 'dialog_gorok_vet', NULL, NULL, NULL, NULL, NULL, '["QUEST"]'::jsonb, '[]'::jsonb, 45)
