values ('npc_wandering_trader', 'Traveling Merchant', 'Rare Goods', 'MERCHANT', 'NONE', 'Roaming — Border Regions', 'CONTESTED', 'The Traveling Merchant has no fixed location and appears at crossroads when least expected. Some say they''re the same person across decades; others say they''re a fleet.', 'mysterious_helpful', 'The rare finds the rare. You''ve found me — so you must be looking for something unusual.', 'shop_rare_01', 'dialog_traveling_trader', NULL, NULL, NULL, NULL, NULL, '["BUY", "SELL"]'::jsonb, '["open_shop"]'::jsonb, 48)
