values ('npc_frontline_commander', 'Commander Tark', 'Frontline Ops', 'QUEST_GIVER', 'CONTESTED', 'Border Skirmish Ring Command Tent', 'BORDER_SKIRMISH_RING', 'Commander Tark leads a multi-faction peacekeeping force that nobody actually obeys. He keeps trying anyway.', 'determined_frustrated', 'Nobody is cooperating. Again. Are you here to help or to make things worse?', NULL, 'dialog_tark_frontline', NULL, NULL, NULL, NULL, NULL, '["QUEST"]'::jsonb, '[]'::jsonb, 50)
