values ('npc_void_walker', 'Nameless Walker', 'Void Touched', 'INFO', 'NONE', 'Void Echo Chasm', 'VOID_ECHO_CHASM', 'The Nameless Walker exists between states — half in this world, half in the Void. They offer guidance but no comfort.', 'unsettling_cryptic', 'You see me. Most do not. That means the Void has noticed you already.', NULL, 'dialog_void_walker', NULL, NULL, NULL, NULL, NULL, '["INFO"]'::jsonb, '[]'::jsonb, 51)
