values ('npc_abyssal_smith', 'Xylar the Abyssal', 'Void Crafter', 'CRAFTER', 'NONE', 'Void Echo Chasm Forge', 'VOID_ECHO_CHASM', 'Xylar the Abyssal forges weapons using Void-touched metal that no standard smith will touch. The products are extraordinary. So is the risk.', 'alien_precise', 'Void-forged items remember their makers. I only work for those who will be remembered in turn.', 'shop_abyssal_smith', 'dialog_xylar_smith', NULL, NULL, NULL, NULL, NULL, '["CRAFT"]'::jsonb, '["open_upgrade"]'::jsonb, 55)
