values ('dialog_fq_conc_044', 'fq_conc_044', 'npc_commander_vale', 'greeting', '[{"id": "greeting", "text": "You''re on time. Aethel Abyssal Reavers have infiltrated the chasm", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The Severance shattered our ability to maintain order. Every day we don''t act, another sector falls to chaos. This mission is how we hold the line.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Your orders: Defeat 5x Aethel Abyssal Reaver; Defeat 3x Void Reaver\n\nComplete and report back.\n\nRewards: 2200 EXP · 1100 Currency · 750 Reputation · Void Crystal Shard", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 74)
