values ('dialog_fq_conc_045', 'fq_conc_045', 'npc_commander_vale', 'greeting', '[{"id": "greeting", "text": "The Concordium needs you. Aethel Corrupted Behemoths guard the path deeper into the chasm", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The Cradle''s infrastructure is fragile. One functioning city, a thousand problems. We fix the cracks before they widen.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Defeat 3x Aethel Corrupted Behemoth; Collect 1x crystal_core\n\nReturn when it''s done. The Concordium keeps score.\n\nRewards: 2500 EXP · 1300 Currency · 650 CRD · 800 Reputation · Corrupted Synapse Cluster", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 75)
