values ('dialog_fq_conc_047', 'fq_conc_047', 'npc_commander_vale', 'greeting', '[{"id": "greeting", "text": "The Concordium needs you. A Gigantic Jotunn guards an ancient gate within the chasm", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "We are not the strongest or richest faction. But we alone believe civilization is worth the cost. Prove that belief isn''t naive.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Your orders: Defeat 1x Gigantic Jotunn; Defeat 4x Void Reaver\n\nComplete and report back.\n\nRewards: 3500 EXP · 1800 Currency · 900 CRD · 1000 Reputation · Titan Core + Con Elite Recovery Pack", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 77)
