values ('dialog_fq_conc_060', 'fq_conc_060', 'npc_commander_vale', 'greeting', '[{"id": "greeting", "text": "You''re on time. THE FINAL VOID TRIAL", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "You earned your position through action, not politics. The Concordium remembers who showed up when walls were crumbling.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Your orders: Defeat 1x Abyss Harbinger; Collect 1x void_core\n\nComplete and report back.\n\nRewards: 15000 EXP · 7500 Currency · 3750 CRD · 5000 Reputation · Void Core + Event Horizon Fragment L", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 90)
