values ('dialog_fq_conc_061', 'fq_conc_061', 'npc_commander_vale', 'greeting', '[{"id": "greeting", "text": "You''re on time. After the Harbinger''s fall, seismic readings spike across Xylos", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The Severance shattered our ability to maintain order. Every day we don''t act, another sector falls to chaos. This mission is how we hold the line.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Your orders: Travel to SEVERANCE_FAULTLINE; Collect 3x stinger_core\n\nComplete and report back.\n\nRewards: 5000 EXP · 2500 Currency · 1250 CRD · 1600 Reputation · Stabilizer Gyro Unit", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 91)
