values ('dialog_fq_conc_062', 'fq_conc_062', 'npc_commander_vale', 'greeting', '[{"id": "greeting", "text": "The Concordium needs you. Aethel Iron Carapaces swarm the faultline, drawn by tectonic energy", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The Severance shattered our ability to maintain order. Every day we don''t act, another sector falls to chaos. This mission is how we hold the line.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Defeat 8x Aethel Iron Carapace; Collect 3x carapace_fragment\n\nReturn when it''s done. The Concordium keeps score.\n\nRewards: 5200 EXP · 2600 Currency · 1300 CRD · 1700 Reputation · Gravity Well Core", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 92)
