values ('dialog_fq_conc_063', 'fq_conc_063', 'npc_commander_vale', 'greeting', '[{"id": "greeting", "text": "Report to me, Operative. Crystal Tyrants are exploiting the unstable terrain", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The Cradle''s infrastructure is fragile. One functioning city, a thousand problems. We fix the cracks before they widen.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Defeat 2x Crystal Tyrant; Defeat 4x Aethel Abyssal Reaver\n\nReturn when it''s done. The Concordium keeps score.\n\nRewards: 6000 EXP · 3000 Currency · 1500 CRD · 2000 Reputation · Quantum Distortion Stone", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 93)
