values ('dialog_fq_conc_076', 'fq_conc_076', 'npc_commander_vale', 'greeting', '[{"id": "greeting", "text": "Report to me, Operative. The Prima Materia War has begun", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "We are not the strongest or richest faction. But we alone believe civilization is worth the cost. Prove that belief isn''t naive.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Defeat 6x Aethel Void Channeler; Defeat 6x Aethel Abyssal Reaver; Collect 2x Raw Aethel Fragment\n\nReturn when it''s done. The Concordium keeps score.\n\nRewards: 7500 EXP · 3800 Currency · 1900 CRD · 2500 Reputation · Power Regulator Core", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 106)
