values ('dialog_fq_conc_077', 'fq_conc_077', 'npc_commander_vale', 'greeting', '[{"id": "greeting", "text": "You''re on time. Residual Gravity Titan energy has spawned Titan Forge Automatons", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "We are not the strongest or richest faction. But we alone believe civilization is worth the cost. Prove that belief isn''t naive.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Defeat 2x Titan Forge Automaton; Collect 1x core_fragment\n\nReturn when it''s done. The Concordium keeps score.\n\nRewards: 8000 EXP · 4000 Currency · 2000 CRD · 2600 Reputation · Processor Cooling Unit", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 107)
