values ('dialog_fq_conc_078', 'fq_conc_078', 'npc_commander_vale', 'greeting', '[{"id": "greeting", "text": "The Concordium needs you. A Titan Proto Core", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "We are not the strongest or richest faction. But we alone believe civilization is worth the cost. Prove that belief isn''t naive.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Defeat 1x Titan Proto Core; Defeat 3x Titan Forge Automaton\n\nReturn when it''s done. The Concordium keeps score.\n\nRewards: 9000 EXP · 4500 Currency · 2250 CRD · 2800 Reputation · Titan Core + Gravity Well Core", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 108)
