values ('dialog_fq_conc_079', 'fq_conc_079', 'npc_commander_vale', 'greeting', '[{"id": "greeting", "text": "At ease, Operative. Sovereign Claim — With the Forge secured, Concordium''s position is unassailable", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The Severance shattered our ability to maintain order. Every day we don''t act, another sector falls to chaos. This mission is how we hold the line.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Your orders: Defeat 1x Gravity Titan; Defeat 1x Abyss Harbinger\n\nComplete and report back.\n\nRewards: 12000 EXP · 6000 Currency · 3000 CRD · 4000 Reputation · Drake Heart + Titan Core", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 109)
