values ('dialog_fq_conc_092', 'fq_conc_092', 'npc_commander_vale', 'greeting', '[{"id": "greeting", "text": "At ease, Operative. Abyssal End — The Abyss is collapsing", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "We are not the strongest or richest faction. But we alone believe civilization is worth the cost. Prove that belief isn''t naive.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Your orders: Defeat 10x Aethel Abyssal Reaver; Defeat 10x Void Reaver\n\nComplete and report back.\n\nRewards: 11000 EXP · 5500 Currency · 2750 CRD · 3500 Reputation · Void Core", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 122)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_fq_conc_093', 'fq_conc_093', 'npc_commander_vale', 'greeting', '[{"id": "greeting", "text": "The Concordium needs you. Crystal Tyrants have made their final stand in the Shattered Heart", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The Cradle''s infrastructure is fragile. One functioning city, a thousand problems. We fix the cracks before they widen.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Your orders: Defeat 3x Crystal Tyrant; Defeat 1x Ashen Drake\n\nComplete and report back.\n\nRewards: 12000 EXP · 6000 Currency · 3000 CRD · 4000 Reputation · Quantum Distortion Stone", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 123)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_fq_conc_094', 'fq_conc_094', 'npc_commander_vale', 'greeting', '[{"id": "greeting", "text": "The Concordium needs you. The Prima Materia Forge must be completely purified of all void corruption", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "You earned your position through action, not politics. The Concordium remembers who showed up when walls were crumbling.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Defeat 8x Aethel Void Channeler; Defeat 3x Titan Forge Automaton\n\nReturn when it''s done. The Concordium keeps score.\n\nRewards: 11000 EXP · 5500 Currency · 2750 CRD · 3500 Reputation · Raw Aethel Core", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 124)
