values ('dialog_fq_conc_095', 'fq_conc_095', 'npc_commander_vale', 'greeting', '[{"id": "greeting", "text": "Report to me, Operative. The Cradle Expanse is now officially Concordium sovereign territory", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "You earned your position through action, not politics. The Concordium remembers who showed up when walls were crumbling.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Defeat 10x Aethel Rift Stalker; Defeat 1x Gravity Titan\n\nReturn when it''s done. The Concordium keeps score.\n\nRewards: 13000 EXP · 6500 Currency · 3250 CRD · 4200 Reputation · Gravity Well Core", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 125)
