values ('dialog_fq_iron_017', 'fq_iron_017', 'npc_warlord_steele', 'greeting', '[{"id": "greeting", "text": "You''ve got that look — ready for something harder. Foreman Brigg has a requisition list from the Bastion''s Titan Assembly program", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The Scrap Fields don''t forgive weakness. Every soldier who''s made it this far knows. The real Hegemony soldiers separate themselves here.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Your orders: Collect 4x Retrieve specified components.; Defeat 3x War Machine Wrecker\n\nStrength prevails.\n\nRewards: 480 EXP · 260 Currency · 260 Reputation · Neural Interface Socket", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 247)
