values ('dialog_fq_iron_033', 'fq_iron_033', 'npc_warlord_steele', 'greeting', '[{"id": "greeting", "text": "Front and center, Soldier. Iron Carapace Breach — Aethel Iron Carapaces are armored threats", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The Scrap Fields don''t forgive weakness. Every soldier who''s made it this far knows. The real Hegemony soldiers separate themselves here.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Defeat 6x Aethel Iron Carapace; Collect 3x Harvest armor plates for the forges.\n\nDon''t come back until it''s done. The Hegemony has no use for half-measures.\n\nRewards: 1400 EXP · 750 Currency · 750 Reputation · Rusted Plate", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 263)
