values ('dialog_fq_iron_039', 'fq_iron_039', 'npc_warlord_steele', 'greeting', '[{"id": "greeting", "text": "War doesn''t wait, Soldier. The Abyss Counter-Offensive has begun", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "A thousand recruits walked through the Bastion gates. A fraction lasted their first week. You''re still standing. Prove there''s more iron in your blood.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Your orders: Defeat 6x Aethel Abyssal Reaver; Defeat 3x Aethel Void Channeler\n\nStrength prevails.\n\nRewards: 2000 EXP · 1100 Currency · 550 CRD · 1100 Reputation · Gravity Well Core", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 269)
