values ('dialog_fq_iron_041', 'fq_iron_041', 'npc_warlord_steele', 'greeting', '[{"id": "greeting", "text": "Front and center, Soldier. Subjugating the Chasm — The Void Echo Chasm is the most hostile environment on Xylos", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "A thousand recruits walked through the Bastion gates. A fraction lasted their first week. You''re still standing. Prove there''s more iron in your blood.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Travel to VOID_ECHO_CHASM; Collect 2x Conduct chasm terrain survey.\n\nDon''t come back until it''s done. The Hegemony has no use for half-measures.\n\nRewards: 1800 EXP · 900 Currency · 450 CRD · 600 Reputation · Void Fragment", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 271)
