values ('dialog_fq_iron_064', 'fq_iron_064', 'npc_warlord_steele', 'greeting', '[{"id": "greeting", "text": "You''ve got that look — ready for something harder. Gigantic Jotunns blockade the main advance route", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The Concordium thinks diplomacy solves everything. The Arcanum thinks reading books does. We know better. Strength is the only language this world understands.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Defeat 3x Gigantic Jotunn; Collect 1x Confirm advance route open.\n\nDon''t come back until it''s done. The Hegemony has no use for half-measures.\n\nRewards: 6500 EXP · 3300 Currency · 1650 CRD · 2100 Reputation · Titan Core", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 294)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
