values ('dialog_fq_iron_082', 'fq_iron_082', 'npc_warlord_steele', 'greeting', '[{"id": "greeting", "text": "Front and center, Soldier. City Garrison — The City has automated defenses", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "A thousand recruits walked through the Bastion gates. A fraction lasted their first week. You''re still standing. Prove there''s more iron in your blood.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Your orders: Defeat 8x Aethel Rift Stalker; Collect 3x Confirm city sectors secured.\n\nStrength prevails.\n\nRewards: 8500 EXP · 4200 Currency · 2100 CRD · 2700 Reputation · Quantum Distortion Stone", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 312)
