values ('dialog_fq_merid_037', 'fq_merid_037', 'npc_don_mox', 'greeting', '[{"id": "greeting", "text": "Ah, Associate. I was just reviewing the ledgers. The Ashen Drake has returned", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The Cartel doesn''t deal in ideology — we deal in opportunity. Every monster cleared is a trade route secured. Every route secured is profit. Simple arithmetic.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Here''s the deal: Defeat 1x Ashen Drake; Collect 1x File Drake asset recovery report.\n\nSimple. Profitable. Done.\n\nRewards: 2500 EXP · 1300 Currency · 650 CRD · 900 Reputation · Drake Heart", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 367)
