values ('dialog_fq_merid_044', 'fq_merid_044', 'npc_don_mox', 'greeting', '[{"id": "greeting", "text": "Come in. Business has been good — but it could be better. Abyssal Reavers contain concentrated void material", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The Cartel doesn''t deal in ideology — we deal in opportunity. Every monster cleared is a trade route secured. Every route secured is profit. Simple arithmetic.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Defeat 6x Aethel Abyssal Reaver; Collect 1x Report harvest yield to the board.\n\nThe Cartel pays well for results, Associate.\n\nRewards: 2200 EXP · 1100 Currency · 550 CRD · 750 Reputation · Void Crystal Shard", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 374)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
