values ('dialog_fq_merid_076', 'fq_merid_076', 'npc_don_mox', 'greeting', '[{"id": "greeting", "text": "Associate! Just who I wanted to see. Production Ramp-Up — The Cartel board demands 300% production increase", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "Port Meridian handles more cargo in a day than the Concordium''s entire logistics division. When something threatens that, we don''t write reports — we pay people to remove threats.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Here''s the deal: Defeat 6x Aethel Void Channeler; Collect 1x Confirm 300% production quota met.\n\nSimple. Profitable. Done.\n\nRewards: 7500 EXP · 3800 Currency · 1900 CRD · 2500 Reputation · Power Regulator Core", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 406)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_fq_merid_077', 'fq_merid_077', 'npc_don_mox', 'greeting', '[{"id": "greeting", "text": "Ah, Associate. I was just reviewing the ledgers. Titan Forge Automatons are superior manufacturing units", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "Port Meridian handles more cargo in a day than the Concordium''s entire logistics division. When something threatens that, we don''t write reports — we pay people to remove threats.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Defeat 3x Titan Forge Automaton; Collect 1x File acquisition status.\n\nThe Cartel pays well for results, Associate.\n\nRewards: 8000 EXP · 4000 Currency · 2000 CRD · 2600 Reputation · Processor Cooling Unit", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 407)
