values ('dialog_fq_merid_093', 'fq_merid_093', 'npc_don_mox', 'greeting', '[{"id": "greeting", "text": "Come in. Business has been good — but it could be better. Crystal Tyrants file for bankruptcy", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The Cartel doesn''t deal in ideology — we deal in opportunity. Every monster cleared is a trade route secured. Every route secured is profit. Simple arithmetic.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Defeat 3x Crystal Tyrant; Collect 1x Certify bankruptcy complete.\n\nThe Cartel pays well for results, Associate.\n\nRewards: 12000 EXP · 6000 Currency · 3000 CRD · 4000 Reputation · Quantum Distortion Stone", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 422)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_fq_merid_094', 'fq_merid_094', 'npc_don_mox', 'greeting', '[{"id": "greeting", "text": "Ah, Associate. I was just reviewing the ledgers. Final quarter earnings report", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "Port Meridian handles more cargo in a day than the Concordium''s entire logistics division. When something threatens that, we don''t write reports — we pay people to remove threats.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Here''s the deal: Defeat 8x Aethel Void Channeler; Defeat 3x Titan Forge Automaton\n\nSimple. Profitable. Done.\n\nRewards: 11000 EXP · 5500 Currency · 2750 CRD · 3500 Reputation · Raw Aethel Core", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 423)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_fq_merid_095', 'fq_merid_095', 'npc_don_mox', 'greeting', '[{"id": "greeting", "text": "Come in. Business has been good — but it could be better. The Cradle Expanse is now a Cartel-exclusive market", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The Cartel doesn''t deal in ideology — we deal in opportunity. Every monster cleared is a trade route secured. Every route secured is profit. Simple arithmetic.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Here''s the deal: Defeat 10x Aethel Rift Stalker; Defeat 1x Gravity Titan\n\nSimple. Profitable. Done.\n\nRewards: 13000 EXP · 6500 Currency · 3250 CRD · 4200 Reputation · Gravity Well Core", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 424)
