values ('dialog_fq_omni_026', 'fq_omni_026', 'npc_director_vey', 'greeting', '[{"id": "greeting", "text": "Cleared for your next assignment. The Cradle Expanse requires orbital monitoring station deployment", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "Every credit invested in you has returned positive value. That is a data point, not a compliment. Based on that data, we''re increasing your operational scope.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Travel to CRADLE_EXPANSE; Collect 2x Deploy surveillance stations.\n\nCompletion: immediate. Compensation: per contract.\n\nRewards: 700 EXP · 400 Currency · 400 Reputation · Con Nutrient Ration", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 454)
