values ('dialog_fq_omni_027', 'fq_omni_027', 'npc_director_vey', 'greeting', '[{"id": "greeting", "text": "Cleared for your next assignment. Aethel Rift Stalkers are biological anomalies", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "Every credit invested in you has returned positive value. That is a data point, not a compliment. Based on that data, we''re increasing your operational scope.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Tasking: Defeat 5x Aethel Rift Stalker; Collect 1x Submit bio-analysis preliminary report.\n\nReport completion via standard channels.\n\nRewards: 750 EXP · 430 Currency · 430 Reputation · Dark Energy Fragment", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 455)
