values ('dialog_fq_omni_060', 'fq_omni_060', 'npc_director_vey', 'greeting', '[{"id": "greeting", "text": "Cleared for your next assignment. FINAL SHUTDOWN SEQUENCE", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "Every credit invested in you has returned positive value. That is a data point, not a compliment. Based on that data, we''re increasing your operational scope.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Tasking: Defeat 1x Abyss Harbinger; Collect 1x Secure the Shutdown Code for Omnicorp.\n\nReport completion via standard channels.\n\nRewards: 15000 EXP · 7500 Currency · 3750 CRD · 5000 Reputation · Void Core + Event Horizon Fragment L", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 488)
