values ('dialog_fq_omni_074', 'fq_omni_074', 'npc_director_vey', 'greeting', '[{"id": "greeting", "text": "OmniCorp''s projections indicate a resource gap requiring intervention. Abyssal forces have entered the Forge", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "Every credit invested in you has returned positive value. That is a data point, not a compliment. Based on that data, we''re increasing your operational scope.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Tasking: Defeat 8x Aethel Abyssal Reaver; Defeat 5x Aethel Void Channeler\n\nReport completion via standard channels.\n\nRewards: 6800 EXP · 3400 Currency · 1700 CRD · 2300 Reputation · Aethel Fragment", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 502)
