values ('dialog_fq_omni_090', 'fq_omni_090', 'npc_director_vey', 'greeting', '[{"id": "greeting", "text": "Asset, your metrics have been reviewed. Source Code Compile — Compile the World Engine source code", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "OmniCorp doesn''t waste resources on sentiment. Every operation is calculated for maximum return. This one is flagged high-yield — your compensation reflects that.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Defeat 10x Aethel Abyssal Reaver; Defeat 2x Crystal Tyrant; Collect 1x Confirm successful compile.\n\nCompletion: immediate. Compensation: per contract.\n\nRewards: 13000 EXP · 6500 Currency · 3250 CRD · 4200 Reputation · Resonanted Astral Phase Crystal", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 518)
