values ('dialog_fq_omni_092', 'fq_omni_092', 'npc_director_vey', 'greeting', '[{"id": "greeting", "text": "Cleared for your next assignment. The void is a deprecated system", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The other factions play politics. OmniCorp plays percentages. We''ve identified a gap impacting quarterly projections. You''re the asset closing that gap.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Tasking: Defeat 10x Aethel Abyssal Reaver; Defeat 10x Void Reaver\n\nReport completion via standard channels.\n\nRewards: 11000 EXP · 5500 Currency · 2750 CRD · 3500 Reputation · Void Core", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 520)
