values ('dialog_fq_omni_098', 'fq_omni_098', 'npc_director_vey', 'greeting', '[{"id": "greeting", "text": "Cleared for your next assignment. Execute the Final Override", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The other factions play politics. OmniCorp plays percentages. We''ve identified a gap impacting quarterly projections. You''re the asset closing that gap.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Tasking: Defeat 1x Gigantic Jotunn; Defeat 1x Ashen Drake; Defeat 1x Abyss Harbinger (+1 more)\n\nReport completion via standard channels.\n\nRewards: 20000 EXP · 10000 Currency · 5000 CRD · 7000 Reputation · Drake Heart + Titan Core", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 526)
