values ('dialog_fq_shard_010', 'fq_shard_010', 'npc_elder_malakor', 'greeting', '[{"id": "greeting", "text": "The Shard has whispered your name. Elder Malakor''s account of the Shardroot Titan is delivered with the solemn...", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The Glowvine Forest sang before the Concordium''s first wall, before the Hegemony''s first weapon. Listen to its song — it guides where weapons and ledgers cannot.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Your path, Child: Defeat 2x Shardroot Titan; Collect 1x ancient_root_core\n\nWalk in the Shard''s light.\n\nRewards: 300 EXP · 180 Currency · 90 CRD · 180 Reputation · Core Fragment", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 538)
