values ('dialog_fq_shard_023', 'fq_shard_023', 'npc_elder_malakor', 'greeting', '[{"id": "greeting", "text": "Peace be with you, Child. The Glowvine has been restless. A Sunken Aethel Leviathan has surfaced near the Heartwood Altar''s sacred wells", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The Shard is not a weapon — it is a living memory of everything before the Severance. Billions of souls, a civilization, compressed into fragments. Shard-touched creatures are echoes.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Your path, Child: Defeat 1x Sunken Aethel Leviathan; Collect 2x leviathan_scale\n\nWalk in the Shard''s light.\n\nRewards: 1750 EXP · 875 Currency · 426 CRD · 545 Reputation · Aethel Core Shard", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 551)
