values ('dialog_fq_shard_036', 'fq_shard_036', 'npc_elder_malakor', 'greeting', '[{"id": "greeting", "text": "The Shard has whispered your name. The Cradle Expanse is the most contested zone on Xylos", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The Shard is not a weapon — it is a living memory of everything before the Severance. Billions of souls, a civilization, compressed into fragments. Shard-touched creatures are echoes.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Your path, Child: Defeat 6x Aethel Rift Stalker; Defeat 3x Aethel Void Channeler\n\nWalk in the Shard''s light.\n\nRewards: 2350 EXP · 1175 Currency · 725 Reputation · Aethel Core Shard", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 564)
