values ('dialog_fq_shard_041', 'fq_shard_041', 'npc_elder_malakor', 'greeting', '[{"id": "greeting", "text": "Come, Child of the Shard. Into the Shard''s First Wound — Elder Malakor calls the Void Echo Chasm ''the wound that never closed''", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The Shard is not a weapon — it is a living memory of everything before the Severance. Billions of souls, a civilization, compressed into fragments. Shard-touched creatures are echoes.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Your path, Child: Travel to VOID_ECHO_CHASM; Collect 3x core_fragment\n\nWalk in the Shard''s light.\n\nRewards: 2600 EXP · 1300 Currency · 630 CRD · 800 Reputation · Aethel Core Shard", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 569)
