insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_fq_shard_084', 'fq_shard_084', 'npc_elder_malakor', 'greeting', '[{"id": "greeting", "text": "Come, Child of the Shard. The Void Tests; The Children Answer — The Cradle Expanse''s purification continues", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The Shard is not a weapon — it is a living memory of everything before the Severance. Billions of souls, a civilization, compressed into fragments. Shard-touched creatures are echoes.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Defeat 5x Aethel Abyssal Reaver\n\nThe Shard''s blessing goes with you, Child.\n\nRewards: 5000 EXP · 2500 Currency · 1250 CRD · 2000 Reputation", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 612)
