values ('dialog_fq_star_010', 'fq_star_010', 'npc_centurion_valka', 'greeting', '[{"id": "greeting", "text": "Stand ready. A Scrapfield Enforcer has occupied the Badlands'' central canyon, disrupting...", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The Starforged Legion crossed the void after our homeworld was destroyed. Billions lost. Everything lost. But the code survived. Every mission declares: the Legion endures.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Mission parameters: Defeat 1x Scrapfield Enforcer; Defeat 2x Badland Brute\n\nComplete with the honor the code demands.\n\nRewards: 300 EXP · 180 Currency · 90 CRD · 180 Reputation · Rusted Plate", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 638)
