values ('dialog_fq_star_011', 'fq_star_011', 'npc_centurion_valka', 'greeting', '[{"id": "greeting", "text": "Legionnaire. Walking Through History — The Mesa Warpath is where the Legion earns its next advancement", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The Legion''s history is written in blood of those before us. Every Legionnaire adds a chapter. Make yours worth reciting.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Mission parameters: Travel to MESA_WARPATH; Collect 1x core_fragment\n\nComplete with the honor the code demands.\n\nRewards: 280 EXP · 150 Currency · 150 Reputation · Con Minor Stim Pack", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 639)
