values ('dialog_fq_star_016', 'fq_star_016', 'npc_centurion_valka', 'greeting', '[{"id": "greeting", "text": "The code demands action. Multiple Warpath Champions are coordinating in the Mesa Warpath''s command canyon", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "Grand Justiciar Aurelius wrote the code in our home star''s ashes. It has never been wrong. When it says advance, we advance. Today it says: prove your worth.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Mission parameters: Defeat 3x Warpath Champion; Collect 1x rare_emblem\n\nComplete with the honor the code demands.\n\nRewards: 520 EXP · 290 Currency · 310 Reputation · Tactical Sensor Cluster", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 644)
