values ('dialog_fq_star_029', 'fq_star_029', 'npc_centurion_valka', 'greeting', '[{"id": "greeting", "text": "The code demands action. The final Titan Assembly Sentinels in the Forge Canyon Depths represent the...", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "Grand Justiciar Aurelius wrote the code in our home star''s ashes. It has never been wrong. When it says advance, we advance. Today it says: prove your worth.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Mission parameters: Defeat 4x Titan Assembly Sentinel; Collect 1x scrap_core\n\nComplete with the honor the code demands.\n\nRewards: 2000 EXP · 1000 Currency · 486 CRD · 620 Reputation · Aethel Core Shard", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 657)
